// Writes the standard API of every resource whose planned routes are the plain ones: list, add,
// read, change and delete. For each such resource it writes layer 1 (the input contract) and layers
// 3 to 7: db-service, service, Route Handlers, API client and hooks.
//
//   pnpm scaffold:api            write the generated files
//   pnpm scaffold:api --check    change nothing; exit 1 if a generated file is out of date
//   pnpm scaffold:api --report   say, module by module, which planned routes exist and which wait
//
// It reads three things: the route tables of the module specifications (which operations a resource
// has, and the permission each needs), the tables as they are in code (which columns exist, which
// are required, which have defaults), and docs/plan/_tools/api-hints.mjs (what neither can say).
//
// What it writes is the part every resource shares, and nothing of a module's own rules. A resource
// gets rules by being taken over: list its table under `handWritten` in the hints and its files are
// no longer written here. Routes that are not plain (approve, publish, collect, compute, reports,
// the family's own routes) are never generated; the report lists them as waiting.
//
// Run with tsx, because it loads the table files.
import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { getColumns } from 'drizzle-orm';
import { getTableConfig } from 'drizzle-orm/pg-core';
import * as prettier from 'prettier';
import { apiHints } from './api-hints.mjs';
import { parseAllSpecs, planDir, repoRoot } from './scaffold-parse.mjs';

const args = process.argv.slice(2);
const checkOnly = args.includes('--check');
const report = args.includes('--report');

const camel = (text) => text.replace(/[_-]([a-z0-9])/g, (_, char) => char.toUpperCase());
const pascal = (text) => camel(text).replace(/^./, (char) => char.toUpperCase());
const lowerFirst = (text) => text.replace(/^./, (char) => char.toLowerCase());
const quote = (text) => `'${String(text).replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
const words = (name) =>
  name
    .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
    .toLowerCase()
    .replace(/^./, (char) => char.toUpperCase());

const problems = [];
const fail = (where, message) => problems.push(`${where}: ${message}`);

// ---------------------------------------------------------------------------------------------
// The tables as they are in code
// ---------------------------------------------------------------------------------------------

// Loading the tables loads the contracts, and with them every contract this scaffolder wrote
// before. The four lists of generated files must therefore exist, and a generated contract that
// no longer loads must not stop its own replacement: its list is emptied, and the next run starts clean.
const emptyList =
  '// Generated by docs/plan/_tools/scaffold-api.mjs. Do not edit: run `pnpm scaffold:api`.\nexport {};\n';
const lists = {
  contracts: join(repoRoot, 'packages/contracts/src/modules/generated-api.ts'),
  core: join(repoRoot, 'packages/core/src/modules/generated.ts'),
  api: join(repoRoot, 'packages/api-client/src/modules/generated.ts'),
  hooks: join(repoRoot, 'packages/hooks/src/modules/generated.ts'),
};
for (const file of Object.values(lists)) {
  if (existsSync(file)) continue;
  mkdirSync(dirname(file), { recursive: true });
  writeFileSync(file, emptyList);
}
let registeredTables;
try {
  ({ registeredTables } = await import('@takhti/db'));
} catch (error) {
  if (checkOnly) throw error;
  writeFileSync(lists.contracts, emptyList);
  console.error(error instanceof Error ? error.message : error);
  console.error(
    '\nThe contracts did not load, so the list of generated contracts was emptied. Run the command again.',
  );
  process.exit(1);
}

// ---------------------------------------------------------------------------------------------
// What the plan says: routes
// ---------------------------------------------------------------------------------------------

const specs = parseAllSpecs();

function routesOf(spec) {
  const lines = readFileSync(join(planDir, '10-modules', spec.file), 'utf8').split(/\r?\n/);
  const routes = [];
  for (let i = 0; i < lines.length; i++) {
    if (!/^\|\s*Method\s*\|\s*Path\s*\|\s*Permission\s*\|\s*Does\s*\|/.test(lines[i])) continue;
    for (let j = i + 2; j < lines.length && lines[j].startsWith('|'); j++) {
      const cells = lines[j]
        .split('|')
        .slice(1, -1)
        .map((cell) => cell.trim());
      routes.push({
        spec,
        method: cells[0],
        path: (cells[1] ?? '').replace(/`/g, ''),
        permission: (cells[2] ?? '').replace(/`/g, ''),
        does: cells[3] ?? '',
      });
    }
  }
  // "Idempotent: `POST /fee-payments`, …" under the route table. A path alone is a POST.
  const idempotent = new Set();
  for (const line of lines) {
    if (!/^Idempotent\b[^:]*:/.test(line)) continue;
    for (const match of line.matchAll(/`(?:(GET|POST|PUT|PATCH|DELETE) )?(\/[^`\s]+)`/g))
      idempotent.add(`${match[1] ?? 'POST'} ${match[2]}`);
  }
  for (const route of routes) route.idempotent = idempotent.has(`${route.method} ${route.path}`);
  return routes;
}

const allRoutes = specs.flatMap(routesOf);
const specTables = new Map();
for (const spec of specs) for (const table of spec.tables) specTables.set(table.name, { spec, table });
const registry = new Map(registeredTables().map((table) => [table.name, table]));

/** The plain operation a route is, when its path is a table's own: `/fee-heads`, `/fee-heads/[id]`. */
function plainOperation(route) {
  const match = route.path.match(/^\/([a-z0-9-]+)(\/\[id\])?(\/restore)?$/);
  if (!match) return undefined;
  const table = match[1].replace(/-/g, '_');
  if (!specTables.has(table)) return undefined;
  const [, , item, restore] = match;
  const operation = restore
    ? route.method === 'POST' && item
      ? 'restore'
      : undefined
    : !item
      ? { GET: 'list', POST: 'create' }[route.method]
      : { GET: 'get', PATCH: 'update', DELETE: 'delete' }[route.method];
  return operation ? { table, segment: match[1], operation } : undefined;
}

// ---------------------------------------------------------------------------------------------
// Which resources get a standard API, and why the others do not
// ---------------------------------------------------------------------------------------------

/** Wave 0 was written by hand in Phase 0; its services are finished by hand in step 2.2. */
const handBuiltModules = new Set(['M00', 'M01', 'M02', 'M03']);
const handWritten = new Set(apiHints.handWritten);

const resources = new Map(); // table name → resource
const waiting = []; // routes left to hand-written services: { route, reason }

for (const route of allRoutes) {
  const plain = plainOperation(route);
  if (!plain) {
    waiting.push({ route, reason: 'not a plain operation' });
    continue;
  }
  const { spec, table } = specTables.get(plain.table);
  const registered = registry.get(plain.table);
  const hint = apiHints.tables[plain.table] ?? {};
  const reason = handBuiltModules.has(spec.code)
    ? 'a Wave 0 resource, finished by hand'
    : !registered
      ? 'its table is not in code'
      : hint.skip
        ? hint.skip
        : registered.scope !== 'org' && registered.scope !== 'branch'
          ? "a list shared by every school, not a school's own records"
          : registered.appendOnly
          ? 'an append-only table: rows are written by a service, never changed'
          : registered.custom
            ? 'a table with a hand-written access rule'
            : registered.staff === 'none'
              ? 'a table staff do not reach directly'
              : !['signed-in'].includes(route.permission) && !route.permission.includes(':')
                ? `open to "${route.permission}", not to members of a school`
                : undefined;
  if (reason) {
    waiting.push({ route, reason });
    continue;
  }
  let resource = resources.get(plain.table);
  if (!resource) {
    resource = { spec, table, registered, segment: plain.segment, operations: {}, routes: [] };
    resources.set(plain.table, resource);
  }
  if (resource.operations[plain.operation])
    fail(plain.table, `the plan lists ${route.method} ${route.path} twice`);
  resource.operations[plain.operation] = route.permission;
  resource.routes.push({ ...route, operation: plain.operation });
}

// ---------------------------------------------------------------------------------------------
// Reading a table: which columns a client sends
// ---------------------------------------------------------------------------------------------

const baseKeys = new Set([
  'id',
  'orgId',
  'version',
  'createdAt',
  'updatedAt',
  'createdBy',
  'updatedBy',
  'deletedAt',
]);

/** Wording in a column's rules that says the server fills it in. */
const serverWording =
  /from the `[a-z_]+` sequence|\bcomputed\b|\bmaintained\b|kept in step|\bcopied\b|the sum of|\bset (when|with|by|on|once)\b|\bfrozen\b|worked out|filled (by|when|in by)|written by the|by the (service|job|system|server|provider|worker)|\bgoes up\b/i;

/** A moment an action stamps, as opposed to a moment a person enters. */
const stampName =
  /^(approved|decided|published|posted|submitted|locked|verified|cancelled|closed|completed|confirmed|reviewed|resolved|acknowledged|rejected|reversed|applied|calculated|computed|sent|delivered|read|printed|issued|revoked|returned|exited|checked_in|checked_out|received|paid|started|finished|ended|generated|synced|seen|opened|removed|handled|escalated|assigned|went_out|came_back|guardian_confirmed|guardian_informed|accepted|ai_accepted|reopened|notified|expired|activated|archived|withdrawn|settled|reconciled|matched|imported|exported|released|voided|refunded|bounced|cleared|datesheet_published|last_[a-z_]+|first_[a-z_]+|next_[a-z_]+)_at$/;

function columnsOf(resource) {
  const { table, registered } = resource;
  const hint = apiHints.tables[table.name] ?? {};
  const forcedServer = new Set(hint.server ?? []);
  const forcedInput = new Set(hint.input ?? []);
  const checks = new Set(getTableConfig(registered.table).checks.map((check) => check.name));
  const list = [];
  for (const [key, column] of Object.entries(getColumns(registered.table))) {
    if (baseKeys.has(key)) continue;
    const spec = table.columns.find((candidate) => candidate.name === column.name);
    const sqlType = column.getSQLType();
    const isArray = (column.dimensions ?? 0) > 0;
    const required = column.notNull && !column.hasDefault && !column.generated;
    const target = spec?.type.target;
    const rules = spec?.rules ?? '';
    let kind = 'input';
    if (column.generated) kind = 'server';
    else if (key === 'branchId' && registered.scope === 'branch') kind = 'branch';
    else if (registered.self === key) kind = 'self';
    else if (forcedInput.has(column.name)) kind = 'input';
    else if (forcedServer.has(column.name)) kind = 'server';
    else if (target === 'profiles' && /_by$/.test(column.name)) kind = required ? 'actor' : 'server';
    else if (target === 'staff' && /_by_staff_id$/.test(column.name)) kind = 'staffBy';
    else if (column.name === 'status') kind = required ? 'input' : 'server';
    else if (stampName.test(column.name) && !required) kind = 'server';
    else if (/_count$/.test(column.name) || column.name === 'times_used') kind = 'server';
    else if (serverWording.test(rules)) kind = 'server';
    list.push({
      key,
      name: column.name,
      sqlType,
      isArray,
      notNull: column.notNull,
      hasDefault: column.hasDefault,
      required,
      isEnum: (column.enumValues?.length ?? 0) > 0,
      target,
      kind,
      // Money that may be negative has no "not below zero" check.
      signed: !checks.has(`${table.name}_${column.name}_min`) && !checks.has(`${table.name}_${column.name}_pos`),
    });
  }
  return list;
}

/** The schema of one field as a client sends it, without `.optional()`. */
function fieldCode(column) {
  const nullable = (code) => (column.notNull ? code : `${code}.nullable()`);
  if (column.isArray) {
    if (column.sqlType === 'uuid') return nullable('z.array(z.uuid())');
    if (column.sqlType === 'text') return nullable('z.array(ShortText)');
    return `shape.${column.key}`;
  }
  if (column.isEnum) return `shape.${column.key}`;
  switch (column.sqlType) {
    case 'uuid':
      return nullable('z.uuid()');
    case 'date':
      return nullable('DateStr');
    case 'time':
      return nullable('TimeStr');
    case 'timestamp with time zone':
      return nullable('Timestamp');
    case 'bigint':
      return nullable(column.signed ? 'SignedMoney' : 'Money');
    case 'boolean':
      return nullable('z.boolean()');
    case 'text':
      if (/(^|_)(phone|mobile)$/.test(column.name)) return nullable('Phone');
      if (/(^|_)email$/.test(column.name)) return nullable('Email');
      return column.notNull ? 'RequiredText' : 'LongText.nullable()';
    default:
      // Whole numbers, decimals and structured values: as the record itself declares them.
      return `shape.${column.key}`;
  }
}

// ---------------------------------------------------------------------------------------------
// Names
// ---------------------------------------------------------------------------------------------

const contractsDir = join(repoRoot, 'packages/contracts/src');
const entityNames = new Map(); // table → entity const name
for (const spec of specs) {
  const file = join(contractsDir, 'modules', spec.key, `${spec.key}.entities.ts`);
  if (!existsSync(file)) continue;
  const text = readFileSync(file, 'utf8');
  // The comment may go on to describe the table, on the same line or over several.
  for (const match of text.matchAll(
    /One row of `([a-z_0-9]+)`, as the API returns it\.(?:(?!\*\/)[\s\S])*\*\/\r?\nexport const ([A-Za-z0-9]+) =/g,
  ))
    entityNames.set(match[1], match[2]);
}

const header = (resource) =>
  `// Generated by docs/plan/_tools/scaffold-api.mjs from docs/plan/10-modules/${resource.spec.file}.\n` +
  '// Do not edit. To give this resource rules of its own, list its table under `handWritten` in\n' +
  '// docs/plan/_tools/api-hints.mjs and take the file over.\n';
const isGenerated = (file) =>
  existsSync(file) && readFileSync(file, 'utf8').startsWith('// Generated by docs/plan/_tools/scaffold-api.mjs');

function namesOf(resource) {
  const plural = pascal(resource.table.name);
  const entity = entityNames.get(resource.table.name);
  if (!entity) fail(resource.table.name, 'has no generated record schema');
  const single = entity ?? plural;
  const file = resource.table.name.replace(/_/g, '-');
  return {
    file,
    entity: single,
    plural,
    create: `Create${single}`,
    update: `Update${single}`,
    list: `List${plural}`,
    listParams: `List${plural}Params`,
    contract: `${lowerFirst(plural)}Contract`,
    tableConst: camel(resource.table.name),
    db: `${lowerFirst(plural)}Db`,
    service: `${lowerFirst(plural)}Service`,
    api: `${lowerFirst(plural)}Api`,
    label: (apiHints.tables[resource.table.name] ?? {}).label ?? words(single),
    /** The records in running text: "behaviour categories". */
    things: words(plural).toLowerCase(),
  };
}

// ---------------------------------------------------------------------------------------------
// Writing: contract
// ---------------------------------------------------------------------------------------------

const primitives = ['DateStr', 'Email', 'LongText', 'Money', 'Phone', 'QueryBool', 'RequiredText', 'ShortText', 'SignedMoney', 'TimeStr', 'Timestamp'];
const uses = (body, name) => new RegExp(`(?<![\\w.])${name}(?!\\w)`).test(body);
const reservedParams = new Set(['page', 'pageSize', 'q', 'sort', 'order']);

/** What the list of a resource can be sorted and filtered by, worked out from its columns. */
function listShape(columns) {
  const byKey = new Map(columns.map((column) => [column.key, column]));
  const sortable = [];
  const add = (key) => {
    if (byKey.has(key) && !sortable.includes(key) && sortable.length < 8) sortable.push(key);
  };
  for (const key of ['sortOrder', 'sequence', 'name', 'title', 'code']) add(key);
  for (const column of columns)
    if (!column.isArray && /(_no|_number)$/.test(column.name) && column.sqlType === 'text') add(column.key);
  const dates = columns.filter(
    (column) => !column.isArray && (column.sqlType === 'date' || column.sqlType === 'timestamp with time zone'),
  );
  for (const column of dates.slice(0, 3)) add(column.key);
  for (const key of ['status', 'kind', 'amount', 'total']) add(key);
  sortable.push('createdAt');

  const first = sortable[0];
  const firstDate = dates[0]?.key;
  const defaultSort = ['sortOrder', 'sequence', 'name', 'title'].includes(first)
    ? first
    : (firstDate && sortable.includes(firstDate) ? firstDate : 'createdAt');
  const defaultOrder = ['sortOrder', 'sequence', 'name', 'title'].includes(defaultSort) ? 'asc' : 'desc';

  const filters = []; // { param, key, kind: 'eq' | 'bool' | 'from' | 'to', code }
  for (const column of columns) {
    if (column.isArray || reservedParams.has(column.key)) continue;
    if (column.sqlType === 'uuid') filters.push({ param: column.key, key: column.key, kind: 'eq', code: 'z.uuid().optional()' });
    else if (column.isEnum)
      filters.push({
        param: column.key,
        key: column.key,
        kind: 'eq',
        code: `shape.${column.key}${column.notNull ? '' : '.unwrap()'}.optional()`,
      });
    else if (column.sqlType === 'boolean')
      filters.push({ param: column.key, key: column.key, kind: 'bool', code: 'QueryBool.optional()' });
  }
  // The first calendar date of the record can be given a range.
  const day = columns.find((column) => !column.isArray && column.sqlType === 'date');
  if (day) {
    filters.push({ param: `${day.key}From`, key: day.key, kind: 'from', code: 'DateStr.optional()' });
    filters.push({ param: `${day.key}To`, key: day.key, kind: 'to', code: 'DateStr.optional()' });
  }

  const search = columns
    .filter(
      (column) =>
        !column.isArray &&
        !column.isEnum &&
        column.sqlType === 'text' &&
        /^(name|name_ur|title|code|full_name|description|phone|email)$|(_no|_number|_name)$/.test(column.name),
    )
    .slice(0, 5)
    .map((column) => column.key);
  return { sortable, defaultSort, defaultOrder, filters, search };
}

/**
 * What a client sends to add and to change a row, and what the service fills in.
 * `create` is undefined when a required column is one only a hand-written service can fill.
 */
function inputsOf(resource, columns) {
  const hint = apiHints.tables[resource.table.name] ?? {};
  const blocking = columns.filter((column) => column.required && column.kind === 'server');
  const wanted = resource.operations.create !== undefined && hint.create !== false;
  const createFields = [];
  const fills = [];
  for (const column of columns) {
    if (column.kind === 'server') continue;
    if (column.kind === 'branch') {
      createFields.push(`${column.key}: z.uuid().optional(),`);
      fills.push(`${column.key}: resolveBranch(ctx, input.${column.key}),`);
    } else if (column.kind === 'self' || column.kind === 'actor') {
      fills.push(`${column.key}: ctx.actor.userId,`);
    } else if (column.kind === 'staffBy') {
      createFields.push(`${column.key}: z.uuid().optional(),`);
      fills.push(
        column.required
          ? `${column.key}: input.${column.key} ?? actorStaffId(ctx),`
          : `${column.key}: input.${column.key} ?? ctx.actor.staffId ?? null,`,
      );
    } else {
      createFields.push(`${column.key}: ${fieldCode(column)}${column.required ? '' : '.optional()'},`);
    }
  }
  // A row keeps the branch, the student, the family and the owner it was made for.
  const fixed = new Set(
    [resource.registered.family, resource.registered.household ? (resource.registered.householdColumn ?? 'familyId') : undefined].filter(Boolean),
  );
  const updateFields = columns
    .filter((column) => column.kind === 'input' && !fixed.has(column.key))
    .map((column) => `${column.key}: ${fieldCode(column)},`);
  return {
    create: wanted && blocking.length === 0 ? { fields: createFields, fills } : undefined,
    createBlockedBy: wanted && blocking.length > 0 ? blocking.map((column) => column.name) : [],
    createHeldBack: resource.operations.create !== undefined && hint.create === false,
    updateFields,
  };
}

function contractCode(resource, names, columns, inputs, list) {
  const { operations } = resource;
  const entitiesFile = `./${resource.spec.key}.entities`;
  const createBody = inputs.create
    ? `z.object({\n  id: z.uuid().optional(),\n${inputs.create.fields.join('\n')}\n})`
    : 'z.never()';
  const updateBody =
    operations.update !== undefined
      ? `z.object({\n${inputs.updateFields.join('\n')}\n}).partial().extend({ version: z.int() })`
      : 'z.object({ version: z.int() })';
  const body =
    `const shape = ${names.entity}.shape;\n\n` +
    (inputs.create
      ? `/** What a client sends to add one. */\n`
      : `/** Adding one is not a plain operation: a service of its own does it. */\n`) +
    `export const ${names.create} = ${createBody};\n` +
    `export type ${names.create} = z.output<typeof ${names.create}>;\n\n` +
    (operations.update !== undefined
      ? `/** What a client sends to change one: any of these fields, and the version it last saw. */\n`
      : `/** Changing one is not a plain operation: a service of its own does it. */\n`) +
    `export const ${names.update} = ${updateBody};\n` +
    `export type ${names.update} = z.output<typeof ${names.update}>;\n\n` +
    `export const ${names.list} = listQuery({\n` +
    `  sortable: [${list.sortable.map(quote).join(', ')}],\n` +
    `  defaultSort: ${quote(list.defaultSort)},\n` +
    `  defaultOrder: ${quote(list.defaultOrder)},\n` +
    `  filters: {\n${list.filters.map((filter) => `    ${filter.param}: ${filter.code},`).join('\n')}\n  },\n` +
    `});\n` +
    `export type ${names.listParams} = z.output<typeof ${names.list}>;\n\n` +
    `export const ${names.contract} = defineResource({\n` +
    `  name: ${quote(resource.segment)},\n` +
    `  path: ${quote(`/${resource.segment}`)},\n` +
    `  entity: ${names.entity},\n` +
    `  create: ${names.create},\n` +
    `  update: ${names.update},\n` +
    `  list: ${names.list},\n` +
    // The plan says adding one must not happen twice: the route then asks for an Idempotency-Key.
    (inputs.create && resource.routes.some((route) => route.operation === 'create' && route.idempotent)
      ? `  idempotentCreate: true,\n`
      : '') +
    `});\n`;
  const usedPrimitives = primitives.filter((name) => uses(body, name));
  const usesShape = /(?<![\w.])shape\./.test(body.replace(`const shape = ${names.entity}.shape;`, ''));
  return (
    header(resource) +
    `import { z } from 'zod';\n` +
    (usedPrimitives.length ? `import { ${usedPrimitives.join(', ')} } from '../../kernel/primitives';\n` : '') +
    `import { defineResource, listQuery } from '../../kernel/resource';\n` +
    `import { ${names.entity} } from ${quote(entitiesFile)};\n\n` +
    (usesShape ? body : body.replace(`const shape = ${names.entity}.shape;\n\n`, ''))
  );
}

// ---------------------------------------------------------------------------------------------
// Writing: db-service, service, routes, client, hooks
// ---------------------------------------------------------------------------------------------

function dbServiceCode(resource, names, list) {
  const t = names.tableConst;
  const branch = resource.registered.scope === 'branch';
  const conditions = [
    ...(branch ? [`branchFilter(ctx, ${t}.branchId),`] : []),
    ...list.filters.map((filter) =>
      filter.kind === 'bool'
        ? `params.${filter.param} !== undefined && eq(${t}.${filter.key}, params.${filter.param}),`
        : filter.kind === 'from'
          ? `params.${filter.param} && gte(${t}.${filter.key}, params.${filter.param}),`
          : filter.kind === 'to'
            ? `params.${filter.param} && lte(${t}.${filter.key}, params.${filter.param}),`
            : `params.${filter.param} && eq(${t}.${filter.key}, params.${filter.param}),`,
    ),
  ];
  const operators = ['eq', 'gte', 'lte'].filter((name) => conditions.some((line) => line.includes(`${name}(`)));
  return (
    header(resource) +
    (operators.length ? `import { ${operators.join(', ')} } from 'drizzle-orm';\n` : '') +
    `import type { ${names.listParams} } from '@takhti/contracts';\n` +
    `import { ${t} } from '@takhti/db';\n` +
    `import { createDbService } from '../../kernel/db-service';\n` +
    (branch ? `import { branchFilter } from '../../kernel/scope';\n` : '') +
    `\n/** Layer 3 for ${names.things}. */\n` +
    `export const ${names.db} = createDbService<typeof ${t}, ${names.listParams}>(${t}, {\n` +
    `  label: ${quote(names.label)},\n` +
    (list.search.length ? `  search: [${list.search.map((key) => `${t}.${key}`).join(', ')}],\n` : '') +
    `  sort: {\n${list.sortable.map((key) => `    ${key}: ${t}.${key},`).join('\n')}\n  },\n` +
    (conditions.length
      ? `  filters: (params${branch ? ', ctx' : ''}) => [\n${conditions.map((line) => `    ${line}`).join('\n')}\n  ],\n`
      : '') +
    `});\n`
  );
}

function serviceCode(resource, names, inputs) {
  const { operations } = resource;
  const read = operations.list ?? operations.get;
  const action = (permission, generated = true) => (permission !== undefined && generated ? quote(permission) : 'false');
  const fills = inputs.create?.fills ?? [];
  const helpers = ['actorStaffId', 'resolveBranch'].filter((name) => fills.some((line) => line.includes(`${name}(`)));
  return (
    header(resource) +
    `import { ${names.contract} } from '@takhti/contracts';\n` +
    `import { createCrudService } from '../../kernel/crud-service';\n` +
    (helpers.length ? `import { ${helpers.join(', ')} } from '../../kernel/scope';\n` : '') +
    `import { ${names.db} } from './${names.file}.db-service';\n\n` +
    `/*\n * Layer 4 for ${names.things}: the plain operations, each behind its permission.\n` +
    ` * The module's own rules (docs/plan/10-modules/${resource.spec.file}, section 5) are not applied here.\n */\n` +
    `export const ${names.service} = createCrudService({\n` +
    `  contract: ${names.contract},\n` +
    `  db: ${names.db},\n` +
    `  module: ${quote(resource.spec.key)},\n` +
    `  actions: {\n` +
    // Listing and opening one record usually need the same permission; the plan sometimes differs.
    (operations.list !== undefined && operations.get !== undefined && operations.list !== operations.get
      ? `    list: ${action(operations.list)},\n    get: ${action(operations.get)},\n`
      : `    read: ${action(read)},\n`) +
    `    create: ${action(operations.create, inputs.create !== undefined)},\n` +
    `    update: ${action(operations.update)},\n` +
    `    delete: ${action(operations.delete)},\n` +
    `    restore: ${action(operations.restore)},\n` +
    `  },\n` +
    (fills.length ? `  toInsert: (input, ctx) => ({\n    ...input,\n${fills.map((line) => `    ${line}`).join('\n')}\n  }),\n` : '') +
    `});\n`
  );
}

const routeFile = (resource, names, builder, methods) =>
  header(resource) +
  `import { ${names.contract} } from '@takhti/contracts';\n` +
  `import { ${names.service} } from '@takhti/core';\n` +
  `import { ${builder} } from '@/server/route';\n\n` +
  `export const { ${methods.join(', ')} } = ${builder}(${names.contract}, ${names.service});\n`;

const apiServiceCode = (resource, names) =>
  header(resource) +
  `import { ${names.contract} } from '@takhti/contracts';\n` +
  `import { createApiService } from '../../kernel/crud-api-service';\n\n` +
  `export const ${names.api} = createApiService(${names.contract});\n`;

function hooksCode(resource, names, inputs) {
  const { operations } = resource;
  const single = names.entity;
  const sameWord = single === names.plural;
  const lines = [
    `export const ${lowerFirst(single)}Keys = crud.keys;`,
    `export const ${lowerFirst(single)}Queries = crud.queries;`,
    ...(operations.list !== undefined ? [`export const use${names.plural}${sameWord ? 'List' : ''} = crud.useList;`] : []),
    ...(operations.get !== undefined ? [`export const use${single} = crud.useDetail;`] : []),
    ...(inputs.create ? [`export const useCreate${single} = crud.useCreate;`] : []),
    ...(operations.update !== undefined ? [`export const useUpdate${single} = crud.useUpdate;`] : []),
    ...(operations.delete !== undefined ? [`export const useDelete${single} = crud.useRemove;`] : []),
  ];
  return (
    header(resource) +
    `import { ${names.api} } from '@takhti/api-client';\n` +
    `import { ${names.contract} } from '@takhti/contracts';\n` +
    `import { createCrudHooks } from '../../kernel/crud-hooks';\n\n` +
    `const crud = createCrudHooks(${names.contract}, ${names.api});\n\n` +
    `${lines.join('\n')}\n`
  );
}

// ---------------------------------------------------------------------------------------------
// Run
// ---------------------------------------------------------------------------------------------

const files = new Map(); // absolute path → content
const built = []; // routes that exist once the files are written
const exportsOf = { contracts: [], core: [], api: [], hooks: [] };
const apiDir = join(repoRoot, 'apps/web/app/api/v1');

const ordered = [...resources.values()].sort((a, b) =>
  a.spec.code === b.spec.code ? a.table.name.localeCompare(b.table.name) : a.spec.code.localeCompare(b.spec.code),
);
for (const resource of ordered) {
  const { operations, spec } = resource;
  const names = namesOf(resource);
  const routesHere = (operation) => resource.routes.filter((route) => route.operation === operation);
  if (handWritten.has(resource.table.name)) {
    for (const route of resource.routes) built.push({ ...route, resource, names, by: 'hand' });
    continue;
  }
  const columns = columnsOf(resource);
  const inputs = inputsOf(resource, columns);
  const list = listShape(columns);

  files.set(join(contractsDir, 'modules', spec.key, `${names.file}.contract.ts`), contractCode(resource, names, columns, inputs, list));
  const coreDir = join(repoRoot, 'packages/core/src/modules', spec.key);
  files.set(join(coreDir, `${names.file}.db-service.ts`), dbServiceCode(resource, names, list));
  files.set(join(coreDir, `${names.file}.service.ts`), serviceCode(resource, names, inputs));
  files.set(join(repoRoot, 'packages/api-client/src/modules', spec.key, `${names.file}.api-service.ts`), apiServiceCode(resource, names));
  files.set(join(repoRoot, 'packages/hooks/src/modules', spec.key, `${names.file}.hooks.ts`), hooksCode(resource, names, inputs));
  exportsOf.contracts.push(`./${spec.key}/${names.file}.contract`);
  exportsOf.core.push(`./${spec.key}/${names.file}.db-service`, `./${spec.key}/${names.file}.service`);
  exportsOf.api.push(`./${spec.key}/${names.file}.api-service`);
  exportsOf.hooks.push(`./${spec.key}/${names.file}.hooks`);

  const collection = [
    ...(operations.list !== undefined ? ['GET'] : []),
    ...(inputs.create ? ['POST'] : []),
  ];
  const item = [
    ...(operations.get !== undefined ? ['GET'] : []),
    ...(operations.update !== undefined ? ['PATCH'] : []),
    ...(operations.delete !== undefined ? ['DELETE'] : []),
  ];
  const place = (file, content) => {
    if (existsSync(file) && !isGenerated(file)) fail(resource.table.name, `${relative(repoRoot, file)} exists and was not generated`);
    else files.set(file, content);
  };
  if (collection.length) place(join(apiDir, resource.segment, 'route.ts'), routeFile(resource, names, 'collectionRoutes', collection));
  if (item.length) place(join(apiDir, resource.segment, '[id]', 'route.ts'), routeFile(resource, names, 'itemRoutes', item));
  if (operations.restore !== undefined)
    place(join(apiDir, resource.segment, '[id]', 'restore', 'route.ts'), routeFile(resource, names, 'restoreRoute', ['POST']));

  for (const operation of ['list', 'get', 'update', 'delete', 'restore'])
    for (const route of routesHere(operation)) built.push({ ...route, resource, names, by: 'scaffold' });
  for (const route of routesHere('create')) {
    if (inputs.create) built.push({ ...route, resource, names, by: 'scaffold' });
    else
      waiting.push({
        route,
        reason: inputs.createHeldBack
          ? 'adding one needs a service of its own (said in the hints)'
          : `adding one needs a service of its own: the server must fill ${inputs.createBlockedBy.join(', ')}`,
      });
  }
}

// ---- the lists each package exports, and the routes the security test walks
const barrel = (paths, what) =>
  '// Generated by docs/plan/_tools/scaffold-api.mjs. Do not edit: run `pnpm scaffold:api`.\n' +
  `/* ${what} */\n` +
  [...paths].sort().map((path) => `export * from ${quote(path)};`).join('\n') +
  '\n';
files.set(lists.contracts, barrel(exportsOf.contracts, 'The input contracts of every resource with a standard API.'));
files.set(lists.core, barrel(exportsOf.core, 'The db-services and services of every resource with a standard API.'));
files.set(lists.api, barrel(exportsOf.api, 'The API clients of every resource with a standard API.'));
files.set(lists.hooks, barrel(exportsOf.hooks, 'The hooks of every resource with a standard API.'));

const routeModule = (route) =>
  route.operation === 'list' || route.operation === 'create'
    ? `${route.resource.segment}/route`
    : route.operation === 'restore'
      ? `${route.resource.segment}/[id]/restore/route`
      : `${route.resource.segment}/[id]/route`;
files.set(
  join(repoRoot, 'tests/api/security/routes.generated.ts'),
  '// Generated by docs/plan/_tools/scaffold-api.mjs. Do not edit: run `pnpm scaffold:api`.\n' +
    `import type { RouteHandler } from '@takhti/core';\n\n` +
    `export interface GeneratedRoute {\n  method: 'GET' | 'POST' | 'PATCH' | 'DELETE';\n  path: string;\n  /** A permission key, or \`signed-in\`. */\n  permission: string;\n  module: string;\n  operation: 'list' | 'create' | 'get' | 'update' | 'delete' | 'restore';\n  load: () => Promise<Partial<Record<'GET' | 'POST' | 'PATCH' | 'DELETE', RouteHandler>>>;\n}\n\n` +
    `/** Every route the API scaffolder wrote, for tests/api/security/routes.generated.test.ts. */\n` +
    `export const generatedRoutes: GeneratedRoute[] = [\n` +
    built
      .filter((route) => route.by === 'scaffold')
      .map(
        (route) =>
          `  { method: ${quote(route.method)}, path: ${quote(route.path)}, permission: ${quote(route.permission)}, module: ${quote(route.resource.spec.key)}, operation: ${quote(route.operation)}, load: () => import(${quote(`../../../apps/web/app/api/v1/${routeModule(route)}`)}) },`,
      )
      .join('\n') +
    '\n];\n',
);

if (problems.length) {
  console.error(problems.join('\n'));
  console.error(`\n${problems.length} problem(s). Nothing was written.`);
  process.exit(1);
}

if (report) {
  const byModule = new Map();
  const row = (code) => byModule.get(code) ?? byModule.set(code, { built: 0, waiting: [] }).get(code);
  for (const route of built) row(route.spec.code).built += 1;
  for (const { route, reason } of waiting) row(route.spec.code).waiting.push({ route, reason });
  for (const spec of specs) {
    const entry = byModule.get(spec.code);
    if (!entry) continue;
    console.log(`\n${spec.code} · ${spec.title}: ${entry.built} route(s) exist, ${entry.waiting.length} wait`);
    if (args.includes('--all'))
      for (const { route, reason } of entry.waiting)
        console.log(`  ${route.method.padEnd(6)} ${route.path}  — ${reason}`);
  }
  const reasons = new Map();
  for (const { reason } of waiting) {
    const key = reason.replace(/: the server must fill .*/, '');
    reasons.set(key, (reasons.get(key) ?? 0) + 1);
  }
  console.log(`\n${built.length} of ${allRoutes.length} planned routes exist as standard operations; ${waiting.length} wait for a hand-written service:`);
  for (const [reason, count] of [...reasons].sort((a, b) => b[1] - a[1])) console.log(`  ${String(count).padStart(4)}  ${reason}`);
  process.exit(0);
}

const stale = [];
let written = 0;
for (const [file, raw] of files) {
  const options = { ...(await prettier.resolveConfig(file)), filepath: file };
  let content = raw;
  // Prettier does not always settle in one pass on long lines.
  for (let pass = 0; pass < 3; pass++) {
    const next = await prettier.format(content, options);
    if (next === content) break;
    content = next;
  }
  const current = existsSync(file) ? readFileSync(file, 'utf8').replace(/\r\n/g, '\n') : undefined;
  if (current === content) continue;
  if (checkOnly) {
    stale.push(relative(repoRoot, file));
    continue;
  }
  mkdirSync(dirname(file), { recursive: true });
  writeFileSync(file, content);
  written++;
}

// A file this scaffolder wrote before and no longer writes (its resource was taken over, or left
// the plan) would otherwise linger and still be served.
const orphans = [];
const walk = (dir) => {
  if (!existsSync(dir)) return;
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) {
      if (entry.name !== 'node_modules') walk(path);
    } else if (/\.ts$/.test(entry.name) && !files.has(path) && isGenerated(path)) orphans.push(path);
  }
};
for (const dir of [contractsDir, join(repoRoot, 'packages/core/src'), join(repoRoot, 'packages/api-client/src'), join(repoRoot, 'packages/hooks/src'), apiDir])
  walk(dir);
// A file taken over by hand has lost its header, so it is not counted here.
const stray = orphans;

if (checkOnly) {
  if (stale.length || stray.length) {
    if (stale.length) console.error(`Out of date (run \`pnpm scaffold:api\`):\n${stale.map((file) => `  ${file}`).join('\n')}`);
    if (stray.length) console.error(`No longer generated (delete, or take over by removing the header):\n${stray.map((file) => `  ${relative(repoRoot, file)}`).join('\n')}`);
    process.exit(1);
  }
  console.log(`Generated API files are up to date: ${files.size} file(s), ${resources.size} resource(s).`);
} else {
  // Nothing is deleted here: a file that is being taken over by hand may still carry the header
  // for a moment, and losing it would lose work. `--check` fails until these are dealt with.
  console.log(
    `${resources.size} resource(s), ${built.length} of ${allRoutes.length} planned routes: ${written} file(s) written, ${files.size - written} unchanged.` +
      (stray.length
        ? `\nThese carry the "Generated by" header but are no longer generated. Delete them, or remove the header if you have taken them over:\n${stray.map((file) => `  ${relative(repoRoot, file)}`).join('\n')}`
        : ''),
  );
  if (stray.length) process.exitCode = 1;
}
